<?php $m=['studentname'=>'name','phone'=>'mobile','doa'=>'joining_date','class'=>'role','rollno'=>'monthly_salary','fathername'=>'father_husband_name','scnic'=>'national_id','fcnic'=>'education','gender'=>'gender','religion'=>'religion','blood'=>'blood_group','health'=>'experience','email'=>'email','dob'=>'date_of_birth','address'=>'home_address'];$v=fn($n)=>old($n,$employee[$m[$n]??$n]??'');$field=function($n,$label,$type='text',$req=false,$extra='')use($v){?><div class="module-field"><label for="<?= $n ?>"><?= e($label) ?><?= $req?' <span class="required">*</span>':'' ?></label><input class="module-input" id="<?= $n ?>" name="<?= $n ?>" type="<?= $type ?>" value="<?= e($v($n)) ?>" <?= $req?'required':'' ?> <?= $extra ?>></div><?php };?>
<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><h1><?= $employee?'Edit Employee':'Add Employee' ?></h1><p>Maintain complete employee master data</p></div></header><form class="form-sections" method="post" enctype="multipart/form-data" action="<?= url($employee?'/admin/employees/'.$employee['id']:'/admin/employees') ?>"><?= csrf_field() ?><section class="module-card"><header class="module-card__header"><h2>Basic Information</h2></header><div class="module-card__body"><div class="module-form-grid module-form-grid--three"><?php $field('studentname','Employee Name','text',true);$field('fileToUpload','Picture','file',false,'accept=".jpg,.jpeg,.png"');$field('phone','Mobile');$field('doa','Date of Joining','date',true);?><div class="module-field"><label for="class">Employee Role <span class="required">*</span></label><select class="module-select" id="class" name="class" required><option value="">Select Role</option><?php foreach(['Principal','Management Staff','Teacher','Accountant','Store Manager','Other']as$r):?><option <?= $v('class')===$r?'selected':'' ?>><?= $r ?></option><?php endforeach ?></select></div><?php $field('rollno','Monthly Salary','number',true,'min="0" step="0.01"');?></div></div></section><section class="module-card"><header class="module-card__header"><h2>Personal &amp; Contact Information</h2></header><div class="module-card__body"><div class="module-form-grid module-form-grid--three"><?php foreach([['fathername','Father / Husband Name'],['scnic','National ID'],['fcnic','Education'],['gender','Gender'],['religion','Religion'],['blood','Blood Group'],['health','Experience'],['email','Email','email'],['dob','Date of Birth','date']]as$f)$field($f[0],$f[1],$f[2]??'text');?><div class="module-field field--wide"><label for="address">Home Address</label><textarea class="module-textarea" id="address" name="address"><?= e($v('address')) ?></textarea></div></div></div></section><div class="action-strip"><a class="btn btn--secondary" href="<?= url('/admin/employees') ?>">Cancel</a><button class="btn btn--primary" type="submit"><?= $employee?'Update Employee':'Create Employee' ?></button></div></form></div></div></main>
